import { isWorkspaceLoaded, deleteWorkspace as deleteWorkspaceFromManager } from '../../../../server/bare/rag-hyperdb/rag-workspace-manager.js';
import { ragDeleteWorkspaceParamsSchema } from '../../../../schemas/index.js';
import { RAGWorkspaceNotFoundError, RAGWorkspaceInUseError } from '../../../../utils/errors-server.js';
export async function deleteWorkspace(params) {
    const { workspace } = ragDeleteWorkspaceParamsSchema.parse(params);
    // Check if workspace is currently in use
    if (isWorkspaceLoaded(workspace)) {
        throw new RAGWorkspaceInUseError(workspace);
    }
    const deleted = await deleteWorkspaceFromManager(workspace);
    if (!deleted) {
        throw new RAGWorkspaceNotFoundError(workspace);
    }
}
